#!/usr/bin/env python3
"""JSON Schema Validator CLI - reimplementation"""
import sys, os, json, re, argparse
from pathlib import Path
from urllib.parse import urlparse, urljoin
import ipaddress

VERSION = "0.41.0"

def compact_json(value):
    return json.dumps(value, separators=(',', ':'), sort_keys=True)

def instance_to_str(value):
    return compact_json(value)

# Format validators
def is_valid_date(s):
    try:
        if not re.match(r'^\d{4}-\d{2}-\d{2}$', s): return False
        y, m, d = int(s[:4]), int(s[5:7]), int(s[8:10])
        if m < 1 or m > 12 or d < 1: return False
        dims = [0,31,28,31,30,31,30,31,31,30,31,30,31]
        if (y%4==0 and y%100!=0) or y%400==0: dims[2]=29
        return d <= dims[m]
    except: return False

def is_valid_time(s):
    m = re.match(r'^(\d{2}):(\d{2}):(\d{2})(\.\d+)?(Z|[+-]\d{2}:\d{2})$', s)
    if not m: return False
    h, mi, sec = int(m.group(1)), int(m.group(2)), int(m.group(3))
    return h <= 23 and mi <= 59 and sec <= 60

def is_valid_datetime(s):
    parts = re.split(r'[Tt]', s, 1)
    return len(parts) == 2 and is_valid_date(parts[0]) and is_valid_time(parts[1])

def is_valid_duration(s):
    if not s.startswith('P'): return False
    if s in ('P', 'PT'): return False
    return bool(re.match(r'^P(?:\d+Y)?(?:\d+M)?(?:\d+W)?(?:\d+D)?(?:T(?:\d+H)?(?:\d+M)?(?:\d+S)?)?$', s))

def is_valid_email(s):
    if not re.match(r'^[^@\s]+@[^@\s]+\.[^@\s]+$', s): return False
    local, domain = s.rsplit('@', 1)
    if not local or '..' in local or local.startswith('.') or local.endswith('.'): return False
    if '..' in domain: return False
    return True

def is_valid_hostname(s):
    if len(s) > 253: return False
    s2 = s.rstrip('.')
    for label in s2.split('.'):
        if not label or len(label) > 63: return False
        if not re.match(r'^[a-zA-Z0-9]([a-zA-Z0-9\-]*[a-zA-Z0-9])?$', label) and not re.match(r'^[a-zA-Z0-9]$', label): return False
    return True

def is_valid_ipv4(s):
    parts = s.split('.')
    if len(parts) != 4: return False
    for p in parts:
        if not p.isdigit() or p != str(int(p)): return False
        if int(p) > 255: return False
    return True

def is_valid_ipv6(s):
    try: ipaddress.IPv6Address(s); return True
    except: return False

def is_valid_uri(s):
    if ' ' in s: return False
    try:
        p = urlparse(s)
        return bool(p.scheme) and bool(re.match(r'^[a-zA-Z][a-zA-Z0-9+\-.]*$', p.scheme))
    except: return False

def is_valid_uri_reference(s):
    return ' ' not in s

def is_valid_iri(s):
    try:
        p = urlparse(s)
        return bool(p.scheme)
    except: return False

def is_valid_uuid(s):
    return bool(re.match(r'^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$', s))

def is_valid_json_pointer(s):
    if s == '': return True
    if not s.startswith('/'): return False
    for part in s[1:].split('/'):
        i = 0
        while i < len(part):
            if part[i] == '~':
                if i+1 >= len(part) or part[i+1] not in '01': return False
                i += 2
            else: i += 1
    return True

def is_valid_relative_json_pointer(s):
    return bool(re.match(r'^\d+(#|(/.*)?)?$', s))

def is_valid_regex(s):
    try: re.compile(s); return True
    except: return False

FORMAT_VALIDATORS = {
    'date': is_valid_date, 'time': is_valid_time, 'date-time': is_valid_datetime,
    'duration': is_valid_duration, 'email': is_valid_email, 'idn-email': lambda s: '@' in s,
    'hostname': is_valid_hostname, 'idn-hostname': lambda s: bool(s) and ' ' not in s,
    'ipv4': is_valid_ipv4, 'ipv6': is_valid_ipv6,
    'uri': is_valid_uri, 'uri-reference': is_valid_uri_reference,
    'iri': is_valid_iri, 'iri-reference': lambda s: '\n' not in s,
    'uuid': is_valid_uuid, 'json-pointer': is_valid_json_pointer,
    'relative-json-pointer': is_valid_relative_json_pointer,
    'regex': is_valid_regex, 'uri-template': lambda s: True,
}

def path_to_ptr(path):
    if not path: return ''
    parts = []
    for p in path:
        s = str(p).replace('~','~0').replace('/','~1')
        parts.append(s)
    return '/' + '/'.join(parts)

def json_equal(a, b):
    if type(a) != type(b):
        if isinstance(a, (int,float)) and isinstance(b, (int,float)) and not isinstance(a,bool) and not isinstance(b,bool):
            return a == b
        return False
    if isinstance(a, dict):
        if set(a.keys()) != set(b.keys()): return False
        return all(json_equal(a[k],b[k]) for k in a)
    if isinstance(a, list):
        if len(a) != len(b): return False
        return all(json_equal(x,y) for x,y in zip(a,b))
    return a == b

def matches_type(instance, type_val):
    types = [type_val] if isinstance(type_val, str) else type_val
    for t in types:
        if t == 'string' and isinstance(instance, str): return True
        if t == 'integer' and isinstance(instance, int) and not isinstance(instance, bool): return True
        if t == 'number' and isinstance(instance, (int,float)) and not isinstance(instance, bool): return True
        if t == 'boolean' and isinstance(instance, bool): return True
        if t == 'null' and instance is None: return True
        if t == 'array' and isinstance(instance, list): return True
        if t == 'object' and isinstance(instance, dict): return True
    return False

class ValidationNode:
    def __init__(self, eval_path, inst_path, schema_uri):
        self.eval_path = eval_path  # list
        self.inst_path = inst_path  # list
        self.schema_uri = schema_uri
        self.valid = True
        self.errors = {}  # keyword -> str or list
        self.annotations = None
        self.dropped_annotations = None
        self.children = []

    def to_dict(self, hierarchical=False):
        d = {}
        if self.annotations is not None: d['annotations'] = self.annotations
        if self.dropped_annotations is not None: d['droppedAnnotations'] = self.dropped_annotations
        if hierarchical and self.children:
            d['details'] = [c.to_dict(hierarchical=True) for c in self.children]
        if self.errors:
            if len(self.errors) == 1:
                k = next(iter(self.errors))
                d['errors'] = {k: self.errors[k]}
            else:
                d['errors'] = dict(self.errors)
        d['evaluationPath'] = path_to_ptr(self.eval_path)
        d['instanceLocation'] = path_to_ptr(self.inst_path)
        d['schemaLocation'] = self.schema_uri + '#' + path_to_ptr(self.eval_path)
        d['valid'] = self.valid
        return d

class SchemaValidator:
    def __init__(self, schema, base_uri='', draft=None, assert_format=False):
        self.root_schema = schema
        self.base_uri = base_uri
        self.assert_format = assert_format
        self.draft = draft if draft is not None else self._detect_draft(schema)

    def _detect_draft(self, schema):
        if not isinstance(schema, dict): return 7
        s = schema.get('$schema', '')
        if 'draft/2020-12' in s: return 2020
        if 'draft/2019-09' in s: return 2019
        if 'draft-07' in s: return 7
        if 'draft-06' in s: return 6
        if 'draft-04' in s: return 4
        return 7

    def _get_id(self, schema):
        if not isinstance(schema, dict): return None
        return schema.get('$id') or (schema.get('id') if self.draft <= 4 else None)

    def _resolve_ref(self, ref, base_uri):
        if ref == '#': return self.root_schema
        if ref.startswith('#/'):
            return self._follow_ptr(self.root_schema, ref[1:])
        if '#' in ref:
            doc_part, ptr = ref.split('#', 1)
            if not doc_part or doc_part == base_uri:
                return self._follow_ptr(self.root_schema, ptr)
        return None

    def _follow_ptr(self, doc, ptr):
        if not ptr: return doc
        if not ptr.startswith('/'): return None
        parts = ptr[1:].split('/')
        cur = doc
        for p in parts:
            p = p.replace('~1','/').replace('~0','~')
            if isinstance(cur, dict):
                if p not in cur: return None
                cur = cur[p]
            elif isinstance(cur, list):
                try: cur = cur[int(p)]
                except: return None
            else: return None
        return cur

    def validate_simple(self, instance):
        """Returns list of error messages (simple validation)"""
        errors = []
        self._validate(self.root_schema, instance, errors, [], self.base_uri)
        return errors

    def _validate(self, schema, instance, errors, path, base_uri):
        if isinstance(schema, bool):
            if not schema:
                errors.append(f"False schema does not allow {instance_to_str(instance)}")
            return
        if not isinstance(schema, dict): return

        sid = self._get_id(schema)
        if sid: base_uri = urljoin(base_uri, sid) if base_uri else sid

        ref = schema.get('$ref')
        if ref is not None:
            resolved = self._resolve_ref(ref, base_uri)
            if resolved is None:
                raise ValueError(f"Pointer '{ref}' does not exist")
            if self.draft < 2019:
                self._validate(resolved, instance, errors, path + ['$ref'], base_uri)
                return
            else:
                self._validate(resolved, instance, errors, path + ['$ref'], base_uri)

        self._apply_keywords(schema, instance, errors, path, base_uri)

    def _apply_keywords(self, schema, instance, errors, path, base_uri):
        # type
        if 'type' in schema:
            tv = schema['type']
            if not matches_type(instance, tv):
                if isinstance(tv, str):
                    errors.append(f"{instance_to_str(instance)} is not of type \"{tv}\"")
                else:
                    stypes = sorted(tv)
                    errors.append(f"{instance_to_str(instance)} is not of types {', '.join(repr(t) for t in stypes)}")

        # enum
        if 'enum' in schema:
            vals = schema['enum']
            if not any(json_equal(instance, v) for v in vals):
                inst = instance_to_str(instance)
                n = len(vals)
                if n == 1:
                    errors.append(f"{inst} is not one of {compact_json(vals[0])}")
                elif n == 2:
                    errors.append(f"{inst} is not one of {compact_json(vals[0])} or {compact_json(vals[1])}")
                elif n == 3:
                    errors.append(f"{inst} is not one of {compact_json(vals[0])}, {compact_json(vals[1])} or {compact_json(vals[2])}")
                else:
                    errors.append(f"{inst} is not one of {compact_json(vals[0])}, {compact_json(vals[1])} or {n-2} other candidates")

        # const
        if 'const' in schema:
            if not json_equal(instance, schema['const']):
                errors.append(f"{compact_json(schema['const'])} was expected")

        # string keywords
        if isinstance(instance, str):
            if 'minLength' in schema:
                ml = schema['minLength']
                if len(instance) < ml:
                    w = "character" if ml == 1 else "characters"
                    errors.append(f"{compact_json(instance)} is shorter than {ml} {w}")
            if 'maxLength' in schema:
                ml = schema['maxLength']
                if len(instance) > ml:
                    w = "character" if ml == 1 else "characters"
                    errors.append(f"{compact_json(instance)} is longer than {ml} {w}")
            if 'pattern' in schema:
                try:
                    if not re.search(schema['pattern'], instance):
                        errors.append(f"{compact_json(instance)} does not match \"{schema['pattern']}\"")
                except: pass
            if 'format' in schema and self.assert_format:
                fmt = schema['format']
                fv = FORMAT_VALIDATORS.get(fmt)
                if fv and not fv(instance):
                    errors.append(f"{compact_json(instance)} is not a \"{fmt}\"")

        # number keywords
        if isinstance(instance, (int, float)) and not isinstance(instance, bool):
            if 'minimum' in schema:
                mn = schema['minimum']
                excl = schema.get('exclusiveMinimum', False)
                if self.draft <= 4 and isinstance(excl, bool):
                    if excl and instance <= mn:
                        errors.append(f"{instance_to_str(instance)} is less than or equal to the minimum of {mn}")
                    elif not excl and instance < mn:
                        errors.append(f"{instance_to_str(instance)} is less than the minimum of {mn}")
                elif instance < mn:
                    errors.append(f"{instance_to_str(instance)} is less than the minimum of {mn}")
            if 'maximum' in schema:
                mx = schema['maximum']
                excl = schema.get('exclusiveMaximum', False)
                if self.draft <= 4 and isinstance(excl, bool):
                    if excl and instance >= mx:
                        errors.append(f"{instance_to_str(instance)} is greater than or equal to the maximum of {mx}")
                    elif not excl and instance > mx:
                        errors.append(f"{instance_to_str(instance)} is greater than the maximum of {mx}")
                elif instance > mx:
                    errors.append(f"{instance_to_str(instance)} is greater than the maximum of {mx}")
            if 'exclusiveMinimum' in schema and self.draft >= 6:
                em = schema['exclusiveMinimum']
                if isinstance(em, (int, float)) and not isinstance(em, bool):
                    if instance <= em:
                        errors.append(f"{instance_to_str(instance)} is less than or equal to the minimum of {em}")
            if 'exclusiveMaximum' in schema and self.draft >= 6:
                em = schema['exclusiveMaximum']
                if isinstance(em, (int, float)) and not isinstance(em, bool):
                    if instance >= em:
                        errors.append(f"{instance_to_str(instance)} is greater than or equal to the maximum of {em}")
            if 'multipleOf' in schema:
                mo = schema['multipleOf']
                if mo > 0:
                    rem = instance % mo
                    tol = 1e-10 * max(abs(instance), abs(mo), 1)
                    if rem > tol and (mo - rem) > tol:
                        errors.append(f"{instance_to_str(instance)} is not a multiple of {mo}")

        # array keywords
        if isinstance(instance, list):
            if 'minItems' in schema:
                mi = schema['minItems']
                if len(instance) < mi:
                    w = "item" if mi == 1 else "items"
                    errors.append(f"{instance_to_str(instance)} has less than {mi} {w}")
            if 'maxItems' in schema:
                mx = schema['maxItems']
                if len(instance) > mx:
                    w = "item" if mx == 1 else "items"
                    errors.append(f"{instance_to_str(instance)} has more than {mx} {w}")
            if schema.get('uniqueItems'):
                seen = []
                dup = False
                for item in instance:
                    for prev in seen:
                        if json_equal(item, prev): dup = True; break
                    if dup: break
                    seen.append(item)
                if dup:
                    errors.append(f"{instance_to_str(instance)} has non-unique elements")
            if 'contains' in schema:
                cs = schema['contains']
                minc = schema.get('minContains', 1)
                maxc = schema.get('maxContains', None)
                count = sum(1 for item in instance if not self._check(cs, item, base_uri))
                # count = number that match
                match_count = sum(1 for item in instance if self._check(cs, item, base_uri))
                if maxc is not None and match_count > maxc:
                    errors.append(f"None of {instance_to_str(instance)} are valid under the given schema")
                elif match_count < minc:
                    errors.append(f"None of {instance_to_str(instance)} are valid under the given schema")
            if self.draft >= 2020:
                prefix_len = 0
                if 'prefixItems' in schema:
                    prefix = schema['prefixItems']
                    prefix_len = len(prefix)
                    for i, (isch, item) in enumerate(zip(prefix, instance)):
                        self._validate(isch, item, errors, path+['prefixItems',i], base_uri)
                if 'items' in schema:
                    items_schema = schema['items']
                    if 'prefixItems' in schema:
                        for i, item in enumerate(instance[prefix_len:], prefix_len):
                            if isinstance(items_schema, bool) and not items_schema:
                                errors.append(f"False schema does not allow {instance_to_str(item)}")
                            elif isinstance(items_schema, dict):
                                self._validate(items_schema, item, errors, path+['items'], base_uri)
                    else:
                        for i, item in enumerate(instance):
                            self._validate(items_schema, item, errors, path+['items',i], base_uri)
            else:
                if 'items' in schema:
                    items = schema['items']
                    if isinstance(items, list):
                        for i, (isch, item) in enumerate(zip(items, instance)):
                            self._validate(isch, item, errors, path+['items',i], base_uri)
                        if 'additionalItems' in schema:
                            ai = schema['additionalItems']
                            for i, item in enumerate(instance[len(items):], len(items)):
                                if isinstance(ai, bool) and not ai:
                                    errors.append(f"Additional items are not allowed ({compact_json(item)} was unexpected)")
                                elif isinstance(ai, dict):
                                    self._validate(ai, item, errors, path+['additionalItems'], base_uri)
                    else:
                        for i, item in enumerate(instance):
                            self._validate(items, item, errors, path+['items',i], base_uri)

        # object keywords
        if isinstance(instance, dict):
            if 'minProperties' in schema:
                mp = schema['minProperties']
                if len(instance) < mp:
                    w = "property" if mp == 1 else "properties"
                    errors.append(f"{instance_to_str(instance)} has less than {mp} {w}")
            if 'maxProperties' in schema:
                mp = schema['maxProperties']
                if len(instance) > mp:
                    w = "property" if mp == 1 else "properties"
                    errors.append(f"{instance_to_str(instance)} has more than {mp} {w}")
            if 'required' in schema:
                for req in schema['required']:
                    if req not in instance:
                        errors.append(f"\"{req}\" is a required property")
            if 'properties' in schema or 'patternProperties' in schema or 'additionalProperties' in schema:
                self._validate_obj_props(schema, instance, errors, path, base_uri)
            if 'propertyNames' in schema:
                pns = schema['propertyNames']
                for prop in instance:
                    self._validate(pns, prop, errors, path+['propertyNames'], base_uri)
            if 'dependencies' in schema and self.draft <= 7:
                for prop, dep in schema['dependencies'].items():
                    if prop in instance:
                        if isinstance(dep, list):
                            for rp in dep:
                                if rp not in instance:
                                    errors.append(f"\"{rp}\" is a required property")
                        else:
                            self._validate(dep, instance, errors, path+['dependencies',prop], base_uri)
            if 'dependentRequired' in schema and self.draft >= 2019:
                for prop, reqs in schema['dependentRequired'].items():
                    if prop in instance:
                        for rp in reqs:
                            if rp not in instance:
                                errors.append(f"\"{rp}\" is a required property")
            if 'unevaluatedProperties' in schema and self.draft >= 2019:
                props = set(schema.get('properties', {}).keys())
                for pat in schema.get('patternProperties', {}):
                    try:
                        for k in instance:
                            if re.search(pat, k): props.add(k)
                    except: pass
                uneval = [k for k in instance if k not in props]
                ups = schema['unevaluatedProperties']
                if isinstance(ups, bool) and not ups and uneval:
                    if len(uneval) == 1:
                        errors.append(f"Unevaluated properties are not allowed ('{uneval[0]}' was unexpected)")
                    else:
                        errors.append(f"Unevaluated properties are not allowed ({', '.join(repr(p) for p in uneval)} were unexpected)")

        # allOf
        if 'allOf' in schema:
            for i, sub in enumerate(schema['allOf']):
                self._validate(sub, instance, errors, path+['allOf',i], base_uri)

        # anyOf
        if 'anyOf' in schema:
            for sub in schema['anyOf']:
                errs = []
                self._validate(sub, instance, errs, [], base_uri)
                if not errs: return
            errors.append(f"{instance_to_str(instance)} is not valid under any of the schemas listed in the 'anyOf' keyword")

        # oneOf
        if 'oneOf' in schema:
            valid_count = sum(1 for sub in schema['oneOf'] if self._check(sub, instance, base_uri))
            if valid_count == 0:
                errors.append(f"{instance_to_str(instance)} is not valid under any of the schemas listed in the 'oneOf' keyword")
            elif valid_count > 1:
                errors.append(f"{instance_to_str(instance)} is valid under more than one of the schemas listed in the 'oneOf' keyword")

        # not
        if 'not' in schema:
            if self._check(schema['not'], instance, base_uri):
                errors.append(f"{compact_json(schema['not'])} is not allowed for {compact_json(instance)}")

        # if/then/else
        if 'if' in schema:
            if_ok = self._check(schema['if'], instance, base_uri)
            if if_ok:
                if 'then' in schema:
                    self._validate(schema['then'], instance, errors, path+['then'], base_uri)
            else:
                if 'else' in schema:
                    self._validate(schema['else'], instance, errors, path+['else'], base_uri)

    def _validate_obj_props(self, schema, instance, errors, path, base_uri):
        props = schema.get('properties', {})
        pat_props = schema.get('patternProperties', {})
        additional = schema.get('additionalProperties', None)

        evaluated = set()
        for prop, psch in props.items():
            if prop in instance:
                evaluated.add(prop)
                self._validate(psch, instance[prop], errors, path+['properties',prop], base_uri)

        for pat, psch in pat_props.items():
            try:
                compiled = re.compile(pat)
                for prop in instance:
                    if compiled.search(prop):
                        evaluated.add(prop)
                        self._validate(psch, instance[prop], errors, path+['patternProperties',pat], base_uri)
            except: pass

        if additional is not None:
            extra = [p for p in instance if p not in evaluated]
            if isinstance(additional, bool) and not additional and extra:
                if len(extra) == 1:
                    errors.append(f"Additional properties are not allowed ('{extra[0]}' was unexpected)")
                else:
                    errors.append(f"Additional properties are not allowed ({', '.join(repr(p) for p in extra)} were unexpected)")
            elif isinstance(additional, dict):
                for prop in [p for p in instance if p not in evaluated]:
                    self._validate(additional, instance[prop], errors, path+['additionalProperties'], base_uri)

    def _check(self, schema, instance, base_uri):
        """Returns True if valid, False if invalid"""
        errs = []
        self._validate(schema, instance, errs, [], base_uri)
        return len(errs) == 0

    def validate_verbose(self, instance):
        """Returns a ValidationNode tree"""
        root_node = ValidationNode([], [], self.base_uri)
        self._eval_verbose(self.root_schema, instance, root_node, [], [], self.base_uri, root_node)
        return root_node

    def _eval_verbose(self, schema, instance, node, eval_path, inst_path, base_uri, root_node):
        """Evaluate schema and build verbose output tree"""
        if isinstance(schema, bool):
            node.valid = schema
            if not schema:
                node.errors['' if not eval_path else str(eval_path[-1])] = \
                    f"False schema does not allow {instance_to_str(instance)}"
            return

        if not isinstance(schema, dict): return

        sid = self._get_id(schema)
        if sid: base_uri = urljoin(base_uri, sid) if base_uri else sid

        ref = schema.get('$ref')
        if ref is not None:
            resolved = self._resolve_ref(ref, base_uri)
            if resolved is None:
                raise ValueError(f"Pointer '{ref}' does not exist")
            ref_path = eval_path + ['$ref']
            ref_node = ValidationNode(ref_path, inst_path, base_uri)
            node.children.append(ref_node)
            self._eval_verbose(resolved, instance, ref_node, ref_path, inst_path, base_uri, root_node)
            if not ref_node.valid:
                node.valid = False
            if self.draft < 2019:
                return

        self._eval_keywords_verbose(schema, instance, node, eval_path, inst_path, base_uri, root_node)

    def _eval_keywords_verbose(self, schema, instance, parent_node, eval_path, inst_path, base_uri, root_node):
        all_valid = True

        def add_leaf(kw, valid, err_msg=None, annotations=None, dropped=None):
            nonlocal all_valid
            kw_path = eval_path + [kw]
            n = ValidationNode(kw_path, inst_path, base_uri)
            n.valid = valid
            if err_msg: n.errors[kw] = err_msg
            if annotations is not None: n.annotations = annotations
            if dropped is not None: n.dropped_annotations = dropped
            if not valid: all_valid = False
            parent_node.children.append(n)
            return n

        def add_child_node(kw_path, inst_p, valid):
            nonlocal all_valid
            n = ValidationNode(kw_path, inst_p, base_uri)
            n.valid = valid
            if not valid: all_valid = False
            parent_node.children.append(n)
            return n

        # type
        if 'type' in schema:
            tv = schema['type']
            if matches_type(instance, tv):
                add_leaf('type', True)
            else:
                if isinstance(tv, str):
                    add_leaf('type', False, f"{instance_to_str(instance)} is not of type \"{tv}\"")
                else:
                    stypes = sorted(tv)
                    add_leaf('type', False, f"{instance_to_str(instance)} is not of types {', '.join(repr(t) for t in stypes)}")

        # enum
        if 'enum' in schema:
            vals = schema['enum']
            if any(json_equal(instance, v) for v in vals):
                add_leaf('enum', True)
            else:
                inst = instance_to_str(instance)
                n = len(vals)
                if n == 1: msg = f"{inst} is not one of {compact_json(vals[0])}"
                elif n == 2: msg = f"{inst} is not one of {compact_json(vals[0])} or {compact_json(vals[1])}"
                elif n == 3: msg = f"{inst} is not one of {compact_json(vals[0])}, {compact_json(vals[1])} or {compact_json(vals[2])}"
                else: msg = f"{inst} is not one of {compact_json(vals[0])}, {compact_json(vals[1])} or {n-2} other candidates"
                add_leaf('enum', False, msg)

        # const
        if 'const' in schema:
            if json_equal(instance, schema['const']): add_leaf('const', True)
            else: add_leaf('const', False, f"{compact_json(schema['const'])} was expected")

        # string keywords
        if isinstance(instance, str):
            if 'minLength' in schema:
                ml = schema['minLength']
                w = "character" if ml == 1 else "characters"
                if len(instance) >= ml: add_leaf('minLength', True)
                else: add_leaf('minLength', False, f"{compact_json(instance)} is shorter than {ml} {w}")
            if 'maxLength' in schema:
                ml = schema['maxLength']
                w = "character" if ml == 1 else "characters"
                if len(instance) <= ml: add_leaf('maxLength', True)
                else: add_leaf('maxLength', False, f"{compact_json(instance)} is longer than {ml} {w}")
            if 'pattern' in schema:
                try:
                    ok = bool(re.search(schema['pattern'], instance))
                except: ok = True
                if ok: add_leaf('pattern', True)
                else: add_leaf('pattern', False, f"{compact_json(instance)} does not match \"{schema['pattern']}\"")
            if 'format' in schema and self.assert_format:
                fmt = schema['format']
                fv = FORMAT_VALIDATORS.get(fmt)
                if fv:
                    if fv(instance): add_leaf('format', True)
                    else: add_leaf('format', False, f"{compact_json(instance)} is not a \"{fmt}\"")
        else:
            # Non-string - these keywords always pass for non-strings
            for kw in ['minLength', 'maxLength', 'pattern']:
                if kw in schema: add_leaf(kw, True)
            if 'format' in schema and self.assert_format:
                add_leaf('format', True)

        # number keywords
        if isinstance(instance, (int, float)) and not isinstance(instance, bool):
            if 'minimum' in schema:
                mn = schema['minimum']
                excl = schema.get('exclusiveMinimum', False)
                if self.draft <= 4 and isinstance(excl, bool):
                    if excl:
                        if instance <= mn: add_leaf('minimum', False, f"{instance_to_str(instance)} is less than or equal to the minimum of {mn}")
                        else: add_leaf('minimum', True)
                    else:
                        if instance < mn: add_leaf('minimum', False, f"{instance_to_str(instance)} is less than the minimum of {mn}")
                        else: add_leaf('minimum', True)
                else:
                    if instance < mn: add_leaf('minimum', False, f"{instance_to_str(instance)} is less than the minimum of {mn}")
                    else: add_leaf('minimum', True)
            if 'maximum' in schema:
                mx = schema['maximum']
                excl = schema.get('exclusiveMaximum', False)
                if self.draft <= 4 and isinstance(excl, bool):
                    if excl:
                        if instance >= mx: add_leaf('maximum', False, f"{instance_to_str(instance)} is greater than or equal to the maximum of {mx}")
                        else: add_leaf('maximum', True)
                    else:
                        if instance > mx: add_leaf('maximum', False, f"{instance_to_str(instance)} is greater than the maximum of {mx}")
                        else: add_leaf('maximum', True)
                else:
                    if instance > mx: add_leaf('maximum', False, f"{instance_to_str(instance)} is greater than the maximum of {mx}")
                    else: add_leaf('maximum', True)
            if 'exclusiveMinimum' in schema and self.draft >= 6:
                em = schema['exclusiveMinimum']
                if isinstance(em, (int, float)) and not isinstance(em, bool):
                    if instance <= em: add_leaf('exclusiveMinimum', False, f"{instance_to_str(instance)} is less than or equal to the minimum of {em}")
                    else: add_leaf('exclusiveMinimum', True)
            if 'exclusiveMaximum' in schema and self.draft >= 6:
                em = schema['exclusiveMaximum']
                if isinstance(em, (int, float)) and not isinstance(em, bool):
                    if instance >= em: add_leaf('exclusiveMaximum', False, f"{instance_to_str(instance)} is greater than or equal to the maximum of {em}")
                    else: add_leaf('exclusiveMaximum', True)
            if 'multipleOf' in schema:
                mo = schema['multipleOf']
                if mo > 0:
                    rem = instance % mo
                    tol = 1e-10 * max(abs(instance), abs(mo), 1)
                    ok = not (rem > tol and (mo - rem) > tol)
                    if ok: add_leaf('multipleOf', True)
                    else: add_leaf('multipleOf', False, f"{instance_to_str(instance)} is not a multiple of {mo}")
        else:
            for kw in ['minimum','maximum','exclusiveMinimum','exclusiveMaximum','multipleOf']:
                if kw in schema: add_leaf(kw, True)

        # array keywords
        if isinstance(instance, list):
            if 'minItems' in schema:
                mi = schema['minItems']
                w = "item" if mi == 1 else "items"
                if len(instance) >= mi: add_leaf('minItems', True)
                else: add_leaf('minItems', False, f"{instance_to_str(instance)} has less than {mi} {w}")
            if 'maxItems' in schema:
                mx = schema['maxItems']
                w = "item" if mx == 1 else "items"
                if len(instance) <= mx: add_leaf('maxItems', True)
                else: add_leaf('maxItems', False, f"{instance_to_str(instance)} has more than {mx} {w}")
            if 'uniqueItems' in schema and schema['uniqueItems']:
                seen = []; dup = False
                for item in instance:
                    for prev in seen:
                        if json_equal(item, prev): dup = True; break
                    if dup: break
                    seen.append(item)
                if dup: add_leaf('uniqueItems', False, f"{instance_to_str(instance)} has non-unique elements")
                else: add_leaf('uniqueItems', True)
            if 'contains' in schema:
                cs = schema['contains']
                minc = schema.get('minContains', 1)
                maxc = schema.get('maxContains', None)
                mc = sum(1 for item in instance if self._check(cs, item, base_uri))
                ok = mc >= minc and (maxc is None or mc <= maxc)
                if ok: add_leaf('contains', True)
                else: add_leaf('contains', False, f"None of {instance_to_str(instance)} are valid under the given schema")

            # items/prefixItems
            if self.draft >= 2020:
                prefix_len = 0
                if 'prefixItems' in schema:
                    prefix = schema['prefixItems']
                    prefix_len = len(prefix)
                    pi_valid = True
                    pi_node = ValidationNode(eval_path+['prefixItems'], inst_path, base_uri)
                    for i, (isch, item) in enumerate(zip(prefix, instance)):
                        child = ValidationNode(eval_path+['prefixItems',i], inst_path+[i], base_uri)
                        pi_node.children.append(child)
                        self._eval_verbose(isch, item, child, eval_path+['prefixItems',i], inst_path+[i], base_uri, root_node)
                        if not child.valid: pi_valid = False
                    pi_node.valid = pi_valid
                    if not pi_valid: all_valid = False
                    parent_node.children.append(pi_node)
                if 'items' in schema:
                    items_schema = schema['items']
                    if 'prefixItems' in schema:
                        extra = instance[prefix_len:]
                        if isinstance(items_schema, bool) and not items_schema:
                            for i, item in enumerate(extra, prefix_len):
                                n = add_leaf('items', False, f"False schema does not allow {instance_to_str(item)}")
                        else:
                            items_valid = True
                            items_node = ValidationNode(eval_path+['items'], inst_path, base_uri)
                            for i, item in enumerate(extra, prefix_len):
                                child = ValidationNode(eval_path+['items'], inst_path+[i], base_uri)
                                items_node.children.append(child)
                                self._eval_verbose(items_schema, item, child, eval_path+['items'], inst_path+[i], base_uri, root_node)
                                if not child.valid: items_valid = False
                            items_node.valid = items_valid
                            if not items_valid: all_valid = False
                            parent_node.children.append(items_node)
                    else:
                        items_valid = True
                        items_node = ValidationNode(eval_path+['items'], inst_path, base_uri)
                        for i, item in enumerate(instance):
                            child = ValidationNode(eval_path+['items',i], inst_path+[i], base_uri)
                            items_node.children.append(child)
                            self._eval_verbose(items_schema, item, child, eval_path+['items',i], inst_path+[i], base_uri, root_node)
                            if not child.valid: items_valid = False
                        items_node.valid = items_valid
                        if not items_valid: all_valid = False
                        parent_node.children.append(items_node)
            else:
                if 'items' in schema:
                    items = schema['items']
                    if isinstance(items, list):
                        # tuple validation
                        for i, (isch, item) in enumerate(zip(items, instance)):
                            child = ValidationNode(eval_path+['items',i], inst_path+[i], base_uri)
                            parent_node.children.append(child)
                            self._eval_verbose(isch, item, child, eval_path+['items',i], inst_path+[i], base_uri, root_node)
                            if not child.valid: all_valid = False
                        if 'additionalItems' in schema:
                            ai = schema['additionalItems']
                            for i, item in enumerate(instance[len(items):], len(items)):
                                if isinstance(ai, bool) and not ai:
                                    n = add_leaf('additionalItems', False, f"Additional items are not allowed ({compact_json(item)} was unexpected)")
                                elif isinstance(ai, dict):
                                    child = ValidationNode(eval_path+['additionalItems'], inst_path+[i], base_uri)
                                    parent_node.children.append(child)
                                    self._eval_verbose(ai, item, child, eval_path+['additionalItems'], inst_path+[i], base_uri, root_node)
                                    if not child.valid: all_valid = False
                    else:
                        items_valid = True
                        for i, item in enumerate(instance):
                            child = ValidationNode(eval_path+['items',i], inst_path+[i], base_uri)
                            parent_node.children.append(child)
                            self._eval_verbose(items, item, child, eval_path+['items',i], inst_path+[i], base_uri, root_node)
                            if not child.valid: items_valid = False; all_valid = False
        else:
            for kw in ['minItems','maxItems','uniqueItems','contains','items','prefixItems','additionalItems']:
                if kw in schema: add_leaf(kw, True)

        # object keywords
        if isinstance(instance, dict):
            if 'minProperties' in schema:
                mp = schema['minProperties']
                w = "property" if mp == 1 else "properties"
                if len(instance) >= mp: add_leaf('minProperties', True)
                else: add_leaf('minProperties', False, f"{instance_to_str(instance)} has less than {mp} {w}")
            if 'maxProperties' in schema:
                mp = schema['maxProperties']
                w = "property" if mp == 1 else "properties"
                if len(instance) <= mp: add_leaf('maxProperties', True)
                else: add_leaf('maxProperties', False, f"{instance_to_str(instance)} has more than {mp} {w}")

            if 'required' in schema:
                reqs = schema['required']
                missing = [r for r in reqs if r not in instance]
                req_node = ValidationNode(eval_path+['required'], inst_path, base_uri)
                if not missing:
                    req_node.valid = True
                    parent_node.children.append(req_node)
                else:
                    req_node.valid = False
                    all_valid = False
                    if len(missing) == 1:
                        req_node.errors['required'] = f"\"{missing[0]}\" is a required property"
                    else:
                        req_node.errors['required'] = [f"\"{m}\" is a required property" for m in missing]
                    parent_node.children.append(req_node)

            # properties / patternProperties / additionalProperties
            has_props = 'properties' in schema
            has_pat = 'patternProperties' in schema
