                    else:
                        add_leaf('unevaluatedProperties', False,
                                 f"Unevaluated properties are not allowed ({', '.join(repr(p) for p in uneval)} were unexpected)")
                else:
                    add_leaf('unevaluatedProperties', True)
        else:
            for kw in ['minProperties','maxProperties','required','properties','patternProperties',
                       'additionalProperties','propertyNames','dependencies','dependentRequired',
                       'unevaluatedProperties']:
