                ao_node.children.append(child)
                self._eval_verbose(sub, instance, child, eval_path+['allOf',i], inst_path, base_uri, root_node)
                if not child.valid: ao_valid = False
            ao_node.valid = ao_valid
            if not ao_valid: all_valid = False
            parent_node.children.append(ao_node)

        # anyOf
        if 'anyOf' in schema:
            any_valid = False
            ao_node = ValidationNode(eval_path+['anyOf'], inst_path, base_uri)
            for i, sub in enumerate(schema['anyOf']):
                child = ValidationNode(eval_path+['anyOf',i], inst_path, base_uri)
                ao_node.children.append(child)
                self._eval_verbose(sub, instance, child, eval_path+['anyOf',i], inst_path, base_uri, root_node)
                if child.valid: any_valid = True
            ao_node.valid = any_valid
            if not any_valid: all_valid = False
            parent_node.children.append(ao_node)

        # oneOf
        if 'oneOf' in schema:
            oo_node = ValidationNode(eval_path+['oneOf'], inst_path, base_uri)
            valid_children = []
            for i, sub in enumerate(schema['oneOf']):
                child = ValidationNode(eval_path+['oneOf',i], inst_path, base_uri)
                oo_node.children.append(child)
                self._eval_verbose(sub, instance, child, eval_path+['oneOf',i], inst_path, base_uri, root_node)
                if child.valid: valid_children.append(i)
            oo_node.valid = len(valid_children) == 1
            if not oo_node.valid: all_valid = False
            parent_node.children.append(oo_node)

        # not
        if 'not' in schema:
            not_valid = not self._check(schema['not'], instance, base_uri)
            add_leaf('not', not_valid)

        # if/then/else
        if 'if' in schema:
            if_node = ValidationNode(eval_path+['if'], inst_path, base_uri)
            self._eval_verbose(schema['if'], instance, if_node, eval_path+['if'], inst_path, base_uri, root_node)
            parent_node.children.append(if_node)

            if if_node.valid:
                if 'then' in schema:
                    then_node = ValidationNode(eval_path+['then'], inst_path, base_uri)
                    self._eval_verbose(schema['then'], instance, then_node, eval_path+['then'], inst_path, base_uri, root_node)
                    parent_node.children.append(then_node)
                    if not then_node.valid: all_valid = False
            else:
                all_valid = False  # if failed
                if 'else' in schema:
                    else_node = ValidationNode(eval_path+['else'], inst_path, base_uri)
                    self._eval_verbose(schema['else'], instance, else_node, eval_path+['else'], inst_path, base_uri, root_node)
                    parent_node.children.append(else_node)
                    if not else_node.valid: all_valid = False

        parent_node.valid = all_valid

    def _eval_props_verbose(self, schema, instance, parent_node, eval_path, inst_path, base_uri, root_node):
        props = schema.get('properties', {})
        pat_props = schema.get('patternProperties', {})
        additional = schema.get('additionalProperties', None)
        has_add = 'additionalProperties' in schema

        evaluated = set()
        prop_children = []  # children under /properties
        pat_children = []   # children under /patternProperties

        for prop, psch in props.items():
            if prop in instance:
                evaluated.add(prop)
                child = ValidationNode(eval_path+['properties',prop], inst_path+[prop], base_uri)
                self._eval_verbose(psch, instance[prop], child, eval_path+['properties',prop], inst_path+[prop], base_uri, root_node)
                prop_children.append((prop, child))

        for pat, psch in pat_props.items():
            try:
                compiled = re.compile(pat)
                for prop in instance:
                    if compiled.search(prop):
                        evaluated.add(prop)
                        child = ValidationNode(eval_path+['patternProperties',pat], inst_path+[prop], base_uri)
                        self._eval_verbose(psch, instance[prop], child, eval_path+['patternProperties',pat], inst_path+[prop], base_uri, root_node)
                        pat_children.append((pat, prop, child))
            except: pass

        if has_add:
            extra = [p for p in instance if p not in evaluated]
            add_valid = True
            if isinstance(additional, bool) and not additional and extra:
                add_valid = False
                if len(extra) == 1:
                    msg = f"Additional properties are not allowed ('{extra[0]}' was unexpected)"
                else:
                    msg = f"Additional properties are not allowed ({', '.join(repr(p) for p in extra)} were unexpected)"
                add_node = ValidationNode(eval_path+['additionalProperties'], inst_path, base_uri)
                add_node.valid = False
                add_node.errors['additionalProperties'] = msg
                parent_node.children.append(add_node)
            elif isinstance(additional, dict):
                add_node = ValidationNode(eval_path+['additionalProperties'], inst_path, base_uri)
                add_node.valid = True
                for prop in extra:
                    child = ValidationNode(eval_path+['additionalProperties'], inst_path+[prop], base_uri)
                    self._eval_verbose(additional, instance[prop], child, eval_path+['additionalProperties'], inst_path+[prop], base_uri, root_node)
                    add_node.children.append(child)
                    if not child.valid: add_node.valid = False; add_valid = False
                parent_node.children.append(add_node)
            else:
                add_node = ValidationNode(eval_path+['additionalProperties'], inst_path, base_uri)
                add_node.valid = True
                parent_node.children.append(add_node)

            # Add property children after additionalProperties
            for prop, child in prop_children:
                parent_node.children.append(child)
        else:
            # No additionalProperties: add properties node
            if props:
                props_valid = all(c.valid for _, c in prop_children)
                matched = sorted([p for p, c in prop_children])
                dropped = sorted([p for p, c in prop_children if not c.valid]) + \
