class VNode:
    """Validation output node"""
    def __init__(self, eval_path, inst_path, base_uri):
        self.eval_path = eval_path
        self.inst_path = inst_path
        self.base_uri = base_uri
        self.valid = True
        self.errors = {}
        self.annotations = None
        self.dropped_annotations = None
        self.children = []

    def to_dict(self, hierarchical=False):
        d = {}
        if self.annotations is not None: d['annotations'] = self.annotations
        if self.dropped_annotations is not None: d['droppedAnnotations'] = self.dropped_annotations
        if hierarchical and self.children:
            d['details'] = [c.to_dict(hierarchical=True) for c in self.children]
        if self.errors:
            if len(self.errors)==1:
                k=next(iter(self.errors)); d['errors']={k: self.errors[k]}
            else: d['errors']=dict(self.errors)
        d['evaluationPath'] = path_to_ptr(self.eval_path)
        d['instanceLocation'] = path_to_ptr(self.inst_path)
        d['schemaLocation'] = self.base_uri + '#' + path_to_ptr(self.eval_path)
        d['valid'] = self.valid
        return d

class VerboseValidator:
    def __init__(self, schema, base_uri='', draft=None, assert_format=False):
