        if 'draft/2019-09' in s: return 2019
        if 'draft-07' in s: return 7
        if 'draft-06' in s: return 6
        if 'draft-04' in s: return 4
        return 7

    def _get_id(self, schema):
        if not isinstance(schema, dict): return None
        if self.draft <= 4: return schema.get('id')
        return schema.get('$id')

    def _resolve_ref(self, ref, base_uri):
        return self._simple._resolve_ref(ref, base_uri)

    def _check(self, schema, instance, base_uri):
        return self._simple._check(schema, instance, base_uri)

    def evaluate(self, instance):
        root = VNode([], [], self.base_uri)
        self._eval(self.root_schema, instance, root, [], [], self.base_uri)
        return root

    def _eval(self, schema, instance, node, eval_path, inst_path, base_uri):
        if isinstance(schema, bool):
            node.valid = schema
            if not schema:
                kw = str(eval_path[-1]) if eval_path else 'schema'
                node.errors[kw] = f"False schema does not allow {instance_to_str(instance)}"
            return
        if not isinstance(schema, dict): return

        sid = self._get_id(schema)
        if sid: base_uri = urljoin(base_uri, sid) if base_uri else sid

        ref = schema.get('$ref')
        if ref is not None:
            resolved = self._resolve_ref(ref, base_uri)
            if resolved is None:
                raise ValueError(f"Pointer '{ref}' does not exist")
            ref_path = eval_path + ['$ref']
            rn = VNode(ref_path, inst_path, base_uri)
            node.children.append(rn)
            self._eval(resolved, instance, rn, ref_path, inst_path, base_uri)
            if not rn.valid: node.valid = False
            if self.draft < 2019: return

        self._eval_kw(schema, instance, node, eval_path, inst_path, base_uri)

