            if self.draft>=2020:
                pfx=schema.get('prefixItems',[])
                if 'prefixItems' in schema:
                    pi_n=VNode(eval_path+['prefixItems'],inst_path,base_uri)
                    pi_n.valid=True
                    for i,(isch,item) in enumerate(zip(pfx,instance)):
                        cn=VNode(eval_path+['prefixItems',i],inst_path+[i],base_uri)
                        pi_n.children.append(cn)
                        self._eval(isch,item,cn,eval_path+['prefixItems',i],inst_path+[i],base_uri)
                        if not cn.valid: pi_n.valid=False; node.valid=False
                    node.children.append(pi_n)
                if 'items' in schema:
                    its=schema['items']; pl=len(pfx)
                    if isinstance(its,bool) and not its:
                        for i,item in enumerate(instance[pl:],pl):
                            self._leaf(node,'items',eval_path,inst_path+[i],base_uri,False,f"False schema does not allow {instance_to_str(item)}")
                    else:
                        it_n=VNode(eval_path+['items'],inst_path,base_uri); it_n.valid=True
                        for i,item in enumerate(instance[pl:],pl):
                            cn=VNode(eval_path+['items'],inst_path+[i],base_uri)
                            it_n.children.append(cn)
                            self._eval(its,item,cn,eval_path+['items'],inst_path+[i],base_uri)
                            if not cn.valid: it_n.valid=False; node.valid=False
                        node.children.append(it_n)
            else:
                if 'items' in schema:
                    its=schema['items']
                    if isinstance(its,list):
                        for i,(isch,item) in enumerate(zip(its,instance)):
                            cn=VNode(eval_path+['items',i],inst_path+[i],base_uri)
                            node.children.append(cn)
                            self._eval(isch,item,cn,eval_path+['items',i],inst_path+[i],base_uri)
                            if not cn.valid: node.valid=False
                        if 'additionalItems' in schema:
                            ai=schema['additionalItems']
                            for i,item in enumerate(instance[len(its):],len(its)):
                                if isinstance(ai,bool) and not ai:
                                    self._leaf(node,'additionalItems',eval_path,inst_path+[i],base_uri,False,f"Additional items are not allowed ({compact_json(item)} was unexpected)")
                                elif isinstance(ai,dict):
                                    cn=VNode(eval_path+['additionalItems'],inst_path+[i],base_uri)
                                    node.children.append(cn)
                                    self._eval(ai,item,cn,eval_path+['additionalItems'],inst_path+[i],base_uri)
                                    if not cn.valid: node.valid=False
                    else:
                        for i,item in enumerate(instance):
                            cn=VNode(eval_path+['items',i],inst_path+[i],base_uri)
                            node.children.append(cn)
                            self._eval(its,item,cn,eval_path+['items',i],inst_path+[i],base_uri)
                            if not cn.valid: node.valid=False
        else:
            for kw in ['minItems','maxItems','uniqueItems','contains','items','prefixItems','additionalItems']:
                if kw in schema: self._leaf(node,kw,eval_path,inst_path,base_uri,True)

        # object keywords
        if isinstance(instance,dict):
            if 'minProperties' in schema:
                mp=schema['minProperties']; w='property' if mp==1 else 'properties'
                if len(instance)>=mp: self._leaf(node,'minProperties',eval_path,inst_path,base_uri,True)
                else: self._leaf(node,'minProperties',eval_path,inst_path,base_uri,False,f"{instance_to_str(instance)} has less than {mp} {w}")
            if 'maxProperties' in schema:
                mp=schema['maxProperties']; w='property' if mp==1 else 'properties'
                if len(instance)<=mp: self._leaf(node,'maxProperties',eval_path,inst_path,base_uri,True)
                else: self._leaf(node,'maxProperties',eval_path,inst_path,base_uri,False,f"{instance_to_str(instance)} has more than {mp} {w}")
            if 'required' in schema:
                reqs=schema['required']
                missing=[r for r in reqs if r not in instance]
                rn=VNode(eval_path+['required'],inst_path,base_uri)
                rn.valid=len(missing)==0
                if missing:
                    if len(missing)==1: rn.errors['required']=f"\"{missing[0]}\" is a required property"
                    else: rn.errors['required']=[f"\"{m}\" is a required property" for m in missing]
                    node.valid=False
                node.children.append(rn)

            has_props='properties' in schema; has_pat='patternProperties' in schema; has_add='additionalProperties' in schema
            if has_props or has_pat or has_add:
                self._eval_props(schema,instance,node,eval_path,inst_path,base_uri)

            if 'propertyNames' in schema:
                pns=schema['propertyNames']
                pn_root=VNode(eval_path+['propertyNames'],inst_path,base_uri); pn_root.valid=True
                for prop in instance:
                    pn_ch=VNode(eval_path+['propertyNames'],inst_path,base_uri)
                    pn_root.children.append(pn_ch)
                    self._eval(pns,prop,pn_ch,eval_path+['propertyNames'],inst_path,base_uri)
                    if not pn_ch.valid: pn_root.valid=False; node.valid=False
                node.children.append(pn_root)

            if 'dependencies' in schema and self.draft<=7:
                for prop,dep in schema['dependencies'].items():
                    if prop in instance:
                        if isinstance(dep,list):
                            dep_n=VNode(eval_path+['dependencies'],inst_path,base_uri); dep_n.valid=True
                            for i,r in enumerate(dep):
                                dn=VNode(eval_path+['dependencies',i],inst_path,base_uri)
                                dn.valid = r in instance
                                if not dn.valid:
                                    dn.errors['dependencies']=f"\"{r}\" is a required property"
                                    dep_n.valid=False; node.valid=False
                                dep_n.children.append(dn)
                            node.children.append(dep_n)
                        else:
                            dep_n=VNode(eval_path+['dependencies',prop],inst_path,base_uri)
                            node.children.append(dep_n)
                            self._eval(dep,instance,dep_n,eval_path+['dependencies',prop],inst_path,base_uri)
                            if not dep_n.valid: node.valid=False

            if 'unevaluatedProperties' in schema and self.draft>=2019:
                props=set(schema.get('properties',{}).keys())
                for pat in schema.get('patternProperties',{}):
                    try:
                        for k in instance:
                            if re.search(pat,k): props.add(k)
                    except: pass
                uneval=[k for k in instance if k not in props]
                ups=schema['unevaluatedProperties']
                if isinstance(ups,bool) and not ups and uneval:
                    if len(uneval)==1: self._leaf(node,'unevaluatedProperties',eval_path,inst_path,base_uri,False,f"Unevaluated properties are not allowed ('{uneval[0]}' was unexpected)")
                    else: self._leaf(node,'unevaluatedProperties',eval_path,inst_path,base_uri,False,f"Unevaluated properties are not allowed ({', '.join(repr(p) for p in uneval)} were unexpected)")
                else: self._leaf(node,'unevaluatedProperties',eval_path,inst_path,base_uri,True)
        else:
            for kw in ['minProperties','maxProperties','required','properties','patternProperties',
                       'additionalProperties','propertyNames','dependencies','dependentRequired','unevaluatedProperties']:
                if kw in schema: self._leaf(node,kw,eval_path,inst_path,base_uri,True)

        # allOf
        if 'allOf' in schema:
            ao=VNode(eval_path+['allOf'],inst_path,base_uri); ao.valid=True
            for i,sub in enumerate(schema['allOf']):
                cn=VNode(eval_path+['allOf',i],inst_path,base_uri)
                ao.children.append(cn)
                self._eval(sub,instance,cn,eval_path+['allOf',i],inst_path,base_uri)
                if not cn.valid: ao.valid=False; node.valid=False
            node.children.append(ao)
        # anyOf
        if 'anyOf' in schema:
            ao=VNode(eval_path+['anyOf'],inst_path,base_uri); ao.valid=False
            for i,sub in enumerate(schema['anyOf']):
                cn=VNode(eval_path+['anyOf',i],inst_path,base_uri)
                ao.children.append(cn)
                self._eval(sub,instance,cn,eval_path+['anyOf',i],inst_path,base_uri)
                if cn.valid: ao.valid=True
            if not ao.valid: node.valid=False
            node.children.append(ao)
        # oneOf
        if 'oneOf' in schema:
            oo=VNode(eval_path+['oneOf'],inst_path,base_uri)
            for i,sub in enumerate(schema['oneOf']):
                cn=VNode(eval_path+['oneOf',i],inst_path,base_uri)
                oo.children.append(cn)
                self._eval(sub,instance,cn,eval_path+['oneOf',i],inst_path,base_uri)
            vc=sum(1 for c in oo.children if c.valid)
            oo.valid = vc==1
            if not oo.valid: node.valid=False
            node.children.append(oo)
        # not
        if 'not' in schema:
            not_ok=not self._check(schema['not'],instance,base_uri)
            self._leaf(node,'not',eval_path,inst_path,base_uri,not_ok)
        # if/then/else
        if 'if' in schema:
            if_n=VNode(eval_path+['if'],inst_path,base_uri)
            node.children.append(if_n)
            self._eval(schema['if'],instance,if_n,eval_path+['if'],inst_path,base_uri)
            if if_n.valid:
                if 'then' in schema:
                    then_n=VNode(eval_path+['then'],inst_path,base_uri)
                    node.children.append(then_n)
                    self._eval(schema['then'],instance,then_n,eval_path+['then'],inst_path,base_uri)
                    if not then_n.valid: node.valid=False
            else:
                node.valid=False
                if 'else' in schema:
                    else_n=VNode(eval_path+['else'],inst_path,base_uri)
                    node.children.append(else_n)
                    self._eval(schema['else'],instance,else_n,eval_path+['else'],inst_path,base_uri)
                    if not else_n.valid: node.valid=False

    def _eval_props(self, schema, instance, node, eval_path, inst_path, base_uri):
        props=schema.get('properties',{})
        pat=schema.get('patternProperties',{})
        add=schema.get('additionalProperties',None)
        has_add='additionalProperties' in schema

        evaluated=set()
        prop_results=[]  # (prop, child_node)
        pat_results=[]   # (pattern, prop, child_node)

        for prop in sorted(props.keys()):
            if prop in instance:
                evaluated.add(prop)
                cn=VNode(eval_path+['properties',prop],inst_path+[prop],base_uri)
                self._eval(props[prop],instance[prop],cn,eval_path+['properties',prop],inst_path+[prop],base_uri)
                prop_results.append((prop,cn))

        for pattern,psch in pat.items():
            try:
                c=re.compile(pattern)
                for prop in instance:
                    if c.search(prop):
                        evaluated.add(prop)
                        cn=VNode(eval_path+['patternProperties',pattern],inst_path+[prop],base_uri)
                        self._eval(psch,instance[prop],cn,eval_path+['patternProperties',pattern],inst_path+[prop],base_uri)
                        pat_results.append((pattern,prop,cn))
            except: pass

        if has_add:
            extra=[p for p in instance if p not in evaluated]
            if isinstance(add,bool) and not add and extra:
                if len(extra)==1: msg=f"Additional properties are not allowed ('{extra[0]}' was unexpected)"
                else: msg=f"Additional properties are not allowed ({', '.join(repr(p) for p in extra)} were unexpected)"
                add_n=VNode(eval_path+['additionalProperties'],inst_path,base_uri)
                add_n.valid=False; add_n.errors['additionalProperties']=msg
                node.valid=False; node.children.append(add_n)
            elif isinstance(add,dict):
                add_n=VNode(eval_path+['additionalProperties'],inst_path,base_uri); add_n.valid=True
                for prop in extra:
                    cn=VNode(eval_path+['additionalProperties'],inst_path+[prop],base_uri)
                    add_n.children.append(cn)
                    self._eval(add,instance[prop],cn,eval_path+['additionalProperties'],inst_path+[prop],base_uri)
                    if not cn.valid: add_n.valid=False; node.valid=False
                node.children.append(add_n)
            else:
                add_n=VNode(eval_path+['additionalProperties'],inst_path,base_uri); add_n.valid=True
                node.children.append(add_n)
            # Add property sub-nodes directly (no /properties wrapper)
            for prop,cn in prop_results:
                node.children.append(cn)
                if not cn.valid: node.valid=False
            # Add pattern sub-nodes directly
            for pattern,prop,cn in pat_results:
                node.children.append(cn)
                if not cn.valid: node.valid=False
        else:
            # No additionalProperties
            if props:
                matched_props=[prop for prop,cn in prop_results]
                all_valid=all(cn.valid for _,cn in prop_results)
                props_n=VNode(eval_path+['properties'],inst_path,base_uri)
                props_n.valid=all_valid
                if all_valid:
                    if matched_props: props_n.annotations=sorted(matched_props)
                else:
                    if matched_props: props_n.dropped_annotations=sorted(matched_props)
                    node.valid=False
                for prop,cn in prop_results:
                    props_n.children.append(cn)
                node.children.append(props_n)
            if pat:
                matched_pat_props=[prop for _,prop,cn in pat_results]
                all_valid_pat=all(cn.valid for _,_,cn in pat_results)
                pat_n=VNode(eval_path+['patternProperties'],inst_path,base_uri)
                pat_n.valid=all_valid_pat
                if all_valid_pat:
                    if matched_pat_props: pat_n.annotations=sorted(set(matched_pat_props))
                else:
                    if matched_pat_props: pat_n.dropped_annotations=sorted(set(matched_pat_props))
                    node.valid=False
                for pattern,prop,cn in pat_results:
                    pat_n.children.append(cn)
                node.children.append(pat_n)

def flatten_nodes(node):
    result=[node]
    for child in node.children: result.extend(flatten_nodes(child))
    return result

def check_schema_validity(schema, draft):
    if isinstance(schema,bool): return None
    if not isinstance(schema,dict): return "Schema must be an object or boolean"
    if 'type' in schema:
        tv=schema['type']
        valid_types={'string','integer','number','boolean','null','array','object'}
        if isinstance(tv,str) and tv not in valid_types:
            return f"\"{tv}\" is not valid under any of the schemas listed in the 'anyOf' keyword"
        elif isinstance(tv,list):
            for t in tv:
                if t not in valid_types:
                    return f"{compact_json(tv)} is not valid under any of the schemas listed in the 'anyOf' keyword"
    return None

def get_schema_uri(schema, schema_path):
    if isinstance(schema,dict):
        sid=schema.get('$id') or schema.get('id','')
        if sid: return sid
    return f"file://{os.path.abspath(schema_path)}"

def main():
    if '-h' in sys.argv or '--help' in sys.argv:
        print("""Usage: executable [OPTIONS] [SCHEMA]

Arguments:
  [SCHEMA]  The JSON Schema to validate with (i.e. schema.json)

Options:
  -i, --instance <INSTANCES>       A path to a JSON instance (i.e. filename.json) to validate (may be specified multiple times)
  -d, --draft <DRAFT>              Enforce a specific JSON Schema draft [possible values: 4, 6, 7, 2019, 2020]
      --assert-format              Turn ON format validation
      --no-assert-format           Turn OFF format validation
      --output <OUTPUT>            Select output style: text (default), flag, list, hierarchical [default: text] [possible values: text, flag, list, hierarchical]
  -v, --version                    Show program's version number and exit
      --errors-only                Only show validation errors
      --connect-timeout <SECONDS>  Timeout for establishing connections (in seconds)
      --timeout <SECONDS>          Total timeout for HTTP requests (in seconds)
  -k, --insecure                   Skip TLS certificate verification (dangerous!)
      --cacert <FILE>              Path to a custom CA certificate file (PEM format)
  -h, --help                       Print help""")
        sys.exit(0)

    parser=argparse.ArgumentParser(prog='executable',add_help=False)
    parser.add_argument('schema',metavar='SCHEMA',nargs='?')
    parser.add_argument('-i','--instance',dest='instances',action='append',metavar='INSTANCES')
    parser.add_argument('-d','--draft',type=int,choices=[4,6,7,2019,2020])
    parser.add_argument('--assert-format',action='store_true')
    parser.add_argument('--no-assert-format',action='store_true')
    parser.add_argument('--output',default='text',choices=['text','flag','list','hierarchical'])
    parser.add_argument('-v','--version',action='store_true')
    parser.add_argument('--errors-only',action='store_true')
    parser.add_argument('--connect-timeout',metavar='SECONDS',type=float)
    parser.add_argument('--timeout',metavar='SECONDS',type=float)
    parser.add_argument('-k','--insecure',action='store_true')
    parser.add_argument('--cacert',metavar='FILE')
    parser.add_argument('-h','--help',action='store_true')
    try: args=parser.parse_args()
    except SystemExit as e: sys.exit(e.code)

    if args.version: print(f"Version: {VERSION}"); sys.exit(0)

    if not args.schema:
        print("error: the following required arguments were not provided:",file=sys.stderr)
        print("  <SCHEMA>",file=sys.stderr)
        print("",file=sys.stderr)
        print("Usage: executable <SCHEMA>",file=sys.stderr)
        print("",file=sys.stderr)
        print("For more information, try '--help'.",file=sys.stderr)
        sys.exit(2)

    try:
        with open(args.schema,'r') as f: schema=json.load(f)
    except FileNotFoundError:
        print("Error: No such file or directory (os error 2)"); sys.exit(1)
    except json.JSONDecodeError as e:
        print(f"Error: {e}"); sys.exit(1)

    draft=args.draft
    if draft is None: draft=SchemaValidator(schema)._detect_draft(schema)
    assert_format=bool(args.assert_format) and not bool(args.no_assert_format)
    schema_uri=get_schema_uri(schema,args.schema)
    base_uri=schema_uri

    if not args.instances:
        err=check_schema_validity(schema,draft)
        if err is None: print("Schema is valid"); sys.exit(0)
        else: print(f"Schema is invalid. Error: {err}"); sys.exit(1)

    exit_code=0
    for inst_path in args.instances:
        try:
            with open(inst_path,'r') as f: instance=json.load(f)
        except FileNotFoundError:
            print("Error: No such file or directory (os error 2)"); sys.exit(1)
        except json.JSONDecodeError as e:
            print(f"Error: {e}"); sys.exit(1)

        if args.output=='text':
            v=SchemaValidator(schema,base_uri=base_uri,draft=draft,assert_format=assert_format)
            errors=[]
            v._validate(schema,instance,errors,base_uri)
            if errors:
                exit_code=1
                print(f"{inst_path} - INVALID. Errors:")
                for i,msg in enumerate(errors,1): print(f"{i}. {msg}")
            else:
                if not args.errors_only: print(f"{inst_path} - VALID")

        elif args.output=='flag':
            v=SchemaValidator(schema,base_uri=base_uri,draft=draft,assert_format=assert_format)
            errors=[]; v._validate(schema,instance,errors,base_uri)
            valid=len(errors)==0
            if not valid: exit_code=1
            if not(args.errors_only and valid):
                r={"instance":inst_path,"output":"flag","payload":{"valid":valid},"schema":args.schema}
                print(compact_json(r))

        elif args.output in ('list','hierarchical'):
            vv=VerboseValidator(schema,base_uri=base_uri,draft=draft,assert_format=assert_format)
            root=vv.evaluate(instance)
            if not root.valid: exit_code=1
            if not(args.errors_only and root.valid):
                if args.output=='list':
                    nodes=flatten_nodes(root)
                    details=[n.to_dict(hierarchical=False) for n in nodes]
                    payload={"details":details,"valid":root.valid}
                else:
                    payload=root.to_dict(hierarchical=True)
                r={"instance":inst_path,"output":args.output,"payload":payload,"schema":args.schema}
                print(compact_json(r))

    sys.exit(exit_code)

if __name__=='__main__':
    main()
